读取并统计：
#include <iostream>
#include <fstream>
#include <cstring>
using namespace std;

int main(){
    ifstream ifile("data.txt");
    int digits=0, letters=0, others=0;
    char ch;
    while(ifile.get(ch)){
        if(ch>='0' && ch<='9')
            digits++;
        else if((ch>='a' && ch<='z') || (ch>='A' && ch<='Z'))
            letters++;
        else if(ch!=' ' && ch!='\t' && ch!='\n') //排除空格、tab、换行
            others++;
    }
    ifile.close();
    cout<<"Digits: "<<digits<<endl;
    cout<<"Letters: "<<letters<<endl;
    cout<<"Others: "<<others<<endl;
    return 0;
}

